 private static final net.minecraft.world.item.ItemStack NATION_BADGE=new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.RED_BANNER),LAND_BADGE=new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.EMERALD_BLOCK);
 static int pinned(){return MarketTheme.c(0xFFE8E9E1);}private final MarketApi api;private final String name,time;private final boolean selected,favorite;
 PrivateChatPeerButton(MarketApi api,String name,String time,int x,int y,int w,boolean selected,OnPress action){super(x,y,w,32,Component.literal(name),action,DEFAULT_NARRATION);this.api=api;this.name=name;this.time=time;this.selected=selected;this.favorite=PaleTaleClient.FAVORITE_PRESENCE.cachedNames().stream().anyMatch(n->n.equalsIgnoreCase(name));setTooltip(net.minecraft.client.gui.components.Tooltip.create(Component.literal(name.contains(":")?name.substring(name.indexOf(":")+1):name)));}
 @Override protected void renderContents(GuiGraphics g,int mx,int my,float delta){int x=getX(),y=getY();var screen=net.minecraft.client.Minecraft.getInstance().screen;int bottom=screen==null?y+32:screen.height-27;g.enableScissor(x,44,x+getWidth(),bottom);boolean tinted=PrivateChatStore.pinned(name);if(selected||isHoveredOrFocused()||tinted)g.fill(x,y,x+getWidth(),y+32,selected?(tinted?MarketTheme.c(0xFF86DB78):MarketTheme.c(0xFF97E688)):isHoveredOrFocused()?(tinted?MarketTheme.c(0xFFDEE1D6):MarketTheme.c(0xFFEAECE5)):pinned());if(name.startsWith("国家:")||name.startsWith("领地:"))MarketTheme.item(g,ChatChannelIcons.icon(name),x+4,y+6,16);else WorldPortrait.draw(g,api,name.startsWith("收藏:")?name.substring(3):name,x+4,y+6,16);boolean player=name.matches("[A-Za-z0-9_]{1,16}");int privateUnread=player?PrivateChatStore.unread(name):0,publicUnread=player?PrivateChatStore.unread("收藏:"+name):PrivateChatStore.unread(name);var font=PaleFont.get();String red=privateUnread>99?"99+":Integer.toString(privateUnread),yellow=publicUnread>99?"99+":Integer.toString(publicUnread);int redWidth=privateUnread>0?font.width(red)+8:0,yellowWidth=publicUnread>0?font.width(yellow)+8:0,reserve=redWidth+yellowWidth;String shown=name.contains(":")?name.substring(name.indexOf(":")+1):name;boolean person=!name.startsWith("领地:")&&!name.startsWith("国家:");if(person){int color=LocalRoster.online(shown)?MarketTheme.c(0xFF278B50):MarketTheme.c(0xFFB43D3D);if(favorite)text(g,"★",x+23,y+5,10,color);else{g.fill(x+26,y+6,x+29,y+11,color);g.fill(x+25,y+7,x+30,y+10,color);}}else MarketTheme.item(g,name.startsWith("国家:")?NATION_BADGE:LAND_BADGE,x+24,y+6,6);boolean pinned=PrivateChatStore.pinned(name),muted=PrivateChatStore.muted(name);int nameWidth=getWidth()-37-reserve-(muted?11:0);text(g,shown,x+34,y+5,nameWidth,INK);if(muted)text(g,"免",x+getWidth()-reserve-12,y+5,10,MUTED);int badgeX=x+getWidth()-reserve-2;if(privateUnread>0){g.fill(badgeX,y+5,badgeX+redWidth-1,y+16,MarketTheme.c(0xFFB43D3D));text(g,red,badgeX+3,y+6,redWidth-4,0xFFFFFFFF);badgeX+=redWidth;}if(publicUnread>0){g.fill(badgeX,y+5,badgeX+yellowWidth-1,y+16,MarketTheme.c(0xFFE1B53F));text(g,yellow,badgeX+3,y+6,yellowWidth-4,0xFFFFFFFF);}text(g,time,x+25,y+18,getWidth()-29,MUTED);g.disableScissor();}
